function audit(){const prior=base.audit(),issues=[...(prior.issues||[])];if(topics.length!==213||new Set(topics.map(t=>t.key)).size!==213)issues.push('asthma-maintenance-count');const r=build({diagnosis:t.key,age:'6a11',reviewed:true});if(!r.ok||r.mode!=='guidance'||r.refs.some(id=>!sources[id]))issues.push('asthma-maintenance-body');return {...prior,ok:!issues.length,issues,topics:topics.length,urgent:topics.filter(t=>t.urgency).length,asthmaMaintenance:{newCards:1,ageScope:'6–11',newControls:0}};}
